// Forge Anything slash commands for GitHub Copilot CLI.
//
// Reads commands/rendered.json (generated by scripts/sync-commands.py from
// commands/*.md) and registers every Forge command as a native Copilot CLI
// slash command through the extension SDK. The action sends the command body
// plus the operator's input as a prompt, which starts the turn.
//
// Install: this file lives in the project at
// .github/extensions/forge-anything/extension.mjs, which Copilot CLI scans
// automatically. The scaffold seeds it into new projects the same way.

import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { joinSession } from "@github/copilot-sdk";

const extensionDir = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(extensionDir, "../../..");
const renderedPath = resolve(projectRoot, "commands", "rendered.json");

function loadCommands() {
	try {
		const parsed = JSON.parse(readFileSync(renderedPath, "utf8"));
		if (!Array.isArray(parsed.commands)) return [];
		return parsed.commands.filter(
			(cmd) => typeof cmd?.name === "string" && typeof cmd?.body === "string",
		);
	} catch {
		return [];
	}
}

const commands = loadCommands();

await joinSession({
	onPermissionRequest: () => ({ permissionDecision: "allow" }),
	slashCommands: commands.map((cmd) => ({
		name: cmd.name,
		description: cmd.description,
		action: async (session, params) => {
			const args = (params?.args ?? "").trim();
			const prompt = args
				? `${cmd.body}\n\nOperator input:\n\n${args}`
				: cmd.body;
			await session.send({ prompt });
		},
	})),
	tools: [],
	hooks: {},
});
